#include "poly.hpp"
int main(int argc,char**argv){if(argc<3){cerr<<"usage: build_square_equations norm_poly.txt output.txt\n";return 2;}try{init();selfchecks();ifstream in(argv[1]);if(!in)throw runtime_error("cannot open input file");int nx,nt;in>>nx>>nt;vector<BP>a(nx);for(int i=0;i<nx;i++){a[i].r.resize(nt);for(int j=0;j<nt;j++)a[i].r[j]=readp(in);a[i].trimself();}Pol l=cuberoot(a.back().r[0]);cerr<<"leading cube root degree "<<l.size()-1<<"; gcd with next "<<gcdp(l,a[nx-2].r[0]).size()-1<<"\n";vector<Pol>lp(100);lp[0]={1};for(int j=1;j<100;j++)lp[j]=fastmul(lp[j-1],l);vector<BP>u(55);vector<int>e(55);u[0].r={{1}};vector<BP>eq;for(int j=1;j<=59;j++){int D=3;for(int r=max(1,j-54);r<j&&r<=54;r++)D=max(D,e[r]+e[j-r]);BP numer=bpol(a[nx-1-j],lp[D-3]);for(int r=max(1,j-54);r<j&&r<=54;r++){int s=j-r;if(r>s)continue;BP v=bpol(bmul(u[r],u[s]),lp[D-e[r]-e[s]]);numer=badd(numer,bscale(v,r==s?4:3));}if(j<=54){numer=bscale(numer,3);while(D>0&&divisible(numer,l)){numer=bdivide(numer,l);D--;}u[j]=move(numer);e[j]=D;cerr<<"sqrt "<<j<<" denominator "<<D<<" deg_s "<<u[j].ns()-1<<" deg_t "<<u[j].r.size()-1<<"\n";}else{Pol gg=l;for(auto&r:numer.r)gg=gcdp(gg,r);while(gg.size()>1){numer=bdivide(numer,gg);gg=l;for(auto&r:numer.r)gg=gcdp(gg,r);}cerr<<"equation "<<j<<" deg_s "<<numer.ns()-1<<" deg_t "<<numer.r.size()-1<<"\n";eq.push_back(move(numer));}}
ofstream out(argv[2]);if(!out)throw runtime_error("cannot open output file");printp(out,l);out<<eq.size()<<'\n';for(auto&p:eq)writebp(out,p);cerr<<"DONE equations\n";
return 0;}catch(exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
